// High-level sketch (C-like, for illustration)
typedef struct block { struct block *next; } block_t;
typedef struct thread_cache { block_t *head; } tcache_t;
typedef struct arena { _Atomic(void*) head; } arena_t;

void* allocate(tcache_t *tc) {
  if (tc->head) { void *p = tc->head; tc->head = tc->head->next; return p; }
  block_t *chunk = arena_fetch_batch();
  // distribute blocks to thread cache and return one
  // ...
  return allocate(tc);
}

void free_(tcache_t *tc, void *p) {
  ((block_t*)p)->next = tc->head;
  tc->head = (block_t*)p;
}
```

